  <script>
    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    function cycleTheme() {
      document.documentElement.classList.toggle('theme-dark');
      document.documentElement.classList.toggle('theme-light');
    }
    function downloadImage() {
      var node = document.getElementById('figure');
      if (!window.htmlToImage || !node) return;
      htmlToImage.toPng(node, { pixelRatio: 2, backgroundColor: '#f3f7fb' }).then(function(dataUrl) {
        var link = document.createElement('a'); link.download = 'ocean-health-indicators.png'; link.href = dataUrl; link.click();
      });
    }

    const colors = {
      temp: '#b2182b',
      ph: '#5b4fa3',
      coral: '#238b45',
      plastic: '#d99100',
      grid: '#d9e4ec',
      text: '#20384d'
    };
    const years = [1990,1992,1994,1996,1998,2000,2002,2004,2006,2008,2010,2012,2014,2015,2016,2017,2018,2019,2020,2021,2022,2023,2024];
    const temp = [0.12,0.04,0.15,0.18,0.28,0.24,0.31,0.36,0.39,0.35,0.44,0.47,0.51,0.57,0.62,0.65,0.59,0.66,0.72,0.76,0.68,0.82,0.91];
    const ph = [8.11,8.107,8.104,8.101,8.098,8.095,8.091,8.087,8.083,8.079,8.075,8.071,8.066,8.064,8.061,8.058,8.055,8.052,8.049,8.046,8.042,8.038,8.034];
    const coral = [33.5,32.8,32.1,31.5,27.2,28.4,27.9,27.3,26.5,25.8,25.1,24.2,23.4,22.6,19.8,18.5,17.9,17.1,16.3,15.4,14.2,12.8,11.5];
    const plastic = [25,30,36,42,49,57,66,76,87,99,112,126,141,149,158,167,177,188,198,210,224,239,255];
    const series = (values) => years.map((year, i) => ({x: year, y: values[i]}));

    const calloutsPlugin = {
      id: 'calloutsPlugin',
      afterDatasetsDraw(chart) {
        const {ctx, chartArea, scales} = chart;
        ctx.save();
        ctx.font = '700 14px Inter, sans-serif';
        ctx.lineWidth = 1.5;
        function callout(text, xScale, yScale, xVal, yVal, tx, ty, color, align) {
          const x = scales[xScale].getPixelForValue(xVal);
          const y = scales[yScale].getPixelForValue(yVal);
          ctx.strokeStyle = color;
          ctx.fillStyle = color;
          ctx.beginPath();
          ctx.moveTo(tx + (align === 'right' ? 150 : -10), ty + 8);
          ctx.lineTo(x, y);
          ctx.stroke();
          ctx.beginPath(); ctx.arc(x, y, 4, 0, Math.PI*2); ctx.fill();
          ctx.fillStyle = '#102033';
          ctx.textAlign = align || 'left';
          const lines = text.split('\n');
          lines.forEach((line, idx) => ctx.fillText(line, tx, ty + idx * 17));
        }
        callout('Sharp recent\nwarming', 'x', 'yTemp', 2024, 0.91, chartArea.right - 180, chartArea.top + 42, colors.temp, 'left');
        callout('Coral decline\nsteepens after 2015', 'x', 'yCoral', 2016, 19.8, chartArea.left + 214, chartArea.bottom - 145, colors.coral, 'left');
        callout('Plastic stock follows\na near-exponential rise', 'x', 'yPlastic', 2024, 255, chartArea.right - 265, chartArea.top + 130, colors.plastic, 'left');
        ctx.restore();
      }
    };

    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return null; }
        try {
          if (this.charts.has(canvasId)) { this.charts.get(canvasId).destroy(); this.charts.delete(canvasId); }
          var ctx = document.getElementById(canvasId);
          if (!ctx) { console.error('Canvas element not found: ' + canvasId); return null; }
          if (ctx.chart) { ctx.chart.destroy(); delete ctx.chart; }
          ctx.setAttribute('role', 'img');
          if (!ctx.getAttribute('aria-label')) ctx.setAttribute('aria-label', 'Chart visualization');
          var chart = new Chart(ctx, config);
          ctx.chart = chart; this.charts.set(canvasId, chart); return chart;
        } catch (error) { console.error('Chart init failed:', error); return null; }
      }
    };

    function initOceanChart() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      Chart.register(calloutsPlugin);
      Chart.defaults.font.family = 'Inter, system-ui, sans-serif';
      Chart.defaults.color = colors.text;
      ChartManager.safeInit('oceanChart', {
        type: 'line',
        data: {
          datasets: [
            {label: 'Sea surface temperature anomaly (°C)', data: series(temp), yAxisID: 'yTemp', borderColor: colors.temp, backgroundColor: 'rgba(178,24,43,0.10)', borderWidth: 4, pointRadius: 3.8, pointHoverRadius: 6, tension: 0.24, fill: false},
            {label: 'Ocean pH (pH)', data: series(ph), yAxisID: 'yPh', borderColor: colors.ph, backgroundColor: colors.ph, borderWidth: 3.2, pointRadius: 3, pointHoverRadius: 5, tension: 0.08, borderDash: [10,6], fill: false},
            {label: 'Hard coral cover (% of reef area)', data: series(coral), yAxisID: 'yCoral', borderColor: colors.coral, backgroundColor: colors.coral, borderWidth: 4.2, pointRadius: 3.8, pointHoverRadius: 6, tension: 0.15, borderDash: [2,5], fill: false},
            {label: 'Ocean plastic pollution (million metric tons)', data: series(plastic), yAxisID: 'yPlastic', borderColor: colors.plastic, backgroundColor: 'rgba(217,145,0,0.18)', borderWidth: 5.6, pointRadius: 4.2, pointHoverRadius: 6, tension: 0.28, fill: false}
          ]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          parsing: false,
          interaction: { mode: 'nearest', intersect: false },
          layout: { padding: { top: 20, right: 26, bottom: 6, left: 22 } },
          plugins: {
            tooltip: {
              enabled: true,
              callbacks: { label: (ctx) => ctx.dataset.label + ': ' + ctx.parsed.y }
            },
            legend: {
              display: true,
              position: 'top',
              align: 'start',
              labels: { usePointStyle: true, boxWidth: 9, boxHeight: 9, padding: 18, color: '#172e42', font: { size: 14, weight: '700' } }
            },
            title: { display: false }
          },
          scales: {
            x: {
              type: 'linear', min: 1990, max: 2024,
              title: { display: true, text: 'Year', color: '#263f55', font: { size: 15, weight: '800' } },
              ticks: { stepSize: 4, callback: v => String(v), color: '#344f65', font: { size: 12, weight: '650' } },
              grid: { color: colors.grid, lineWidth: 1, tickLength: 4 },
              border: { color: '#8fa7ba' }
            },
            yTemp: {
              position: 'left', min: 0, max: 1.0,
              title: { display: true, text: 'Temperature anomaly (°C)', color: colors.temp, font: { size: 14, weight: '850' } },
              ticks: { color: colors.temp, font: { size: 12, weight: '750' }, callback: v => Number(v).toFixed(1) },
              grid: { color: '#e3ebf1' }, border: { color: colors.temp, width: 2 }
            },
            yPh: {
              position: 'left', min: 8.03, max: 8.115, offset: true,
              title: { display: true, text: 'Ocean surface pH', color: colors.ph, font: { size: 14, weight: '850' } },
              ticks: { color: colors.ph, font: { size: 12, weight: '750' }, callback: v => Number(v).toFixed(3) },
              grid: { drawOnChartArea: false }, border: { color: colors.ph, width: 2 }
            },
            yCoral: {
              position: 'right', min: 10, max: 35,
              title: { display: true, text: 'Hard coral cover (% of reef area)', color: colors.coral, font: { size: 14, weight: '850' } },
              ticks: { color: colors.coral, font: { size: 12, weight: '750' }, callback: v => v + '%' },
              grid: { drawOnChartArea: false }, border: { color: colors.coral, width: 2 }
            },
            yPlastic: {
              position: 'right', min: 0, max: 280, offset: true,
              title: { display: true, text: 'Plastic pollution stock (million metric tons)', color: colors.plastic, font: { size: 14, weight: '850' } },
              ticks: { color: colors.plastic, font: { size: 12, weight: '750' }, callback: v => v },
              grid: { drawOnChartArea: false }, border: { color: colors.plastic, width: 2 }
            }
          }
        }
      });
    }
    window.addEventListener('load', initOceanChart);
  </script>
